function setValuationOutputMetrics(){
  const sh = ss.getSheetByName('Valuation Output');
  const rows = [7,8,9,10,11,12];

  sh.getRange('D7:D12').setFormulas(rows.map(r => [`='Scenario Engine'!F${r}*Assumptions!F13`]));
  sh.getRange('I7:I12').setFormulas(rows.map(r => [`='Scenario Engine'!D${r}`]));
  sh.getRange('L7:L12').setFormulas(rows.map(r => [`='Scenario Engine'!G${r}*'Scenario Engine'!E${r}`]));
  sh.getRange('S7:S12').setFormulas(rows.map(r => [`='Valuation Output'!P${r}`]));
  sh.getRange('T7:T12').setFormulas(rows.map(r => [`=SUM('Valuation Output'!R${r},-'Valuation Output'!S${r},'Scenario Engine'!L${r}:Q${r})`]));
  sh.getRange('V7:V12').setFormulas(rows.map(r => [`='Valuation Output'!U${r}/Assumptions!J16`]));
  sh.getRange('AA7:AB12').setFormulas(rows.map(r => [
    `='Valuation Output'!Z${r}-Assumptions!J12`,
    `='Valuation Output'!AA${r}/Assumptions!J12`
  ]));
  sh.getRange('AD7:AF12').setFormulas(rows.map(r => [
    `=SUM('Valuation Output'!U${r},-'Valuation Output'!P${r},'Scenario Engine'!L${r}:Q${r})`,
    `='Valuation Output'!AD${r}/Assumptions!J15`,
    `='Valuation Output'!AD${r}/Assumptions!J14`
  ]));
  SpreadsheetApp.flush();

  const check = sh.getRange('D7:AF12').getDisplayValues();
  log({
    row7: check[0],
    row12: check[5]
  });
}
setValuationOutputMetrics();
